class Solution {
public:
    int minimumBoxes(vector<int>& apple, vector<int>& capacity) {
        int total = 0;
        for (int a : apple) total += a;
        sort(capacity.begin(), capacity.end(), greater<int>());
        int sum = 0, count = 0;
        for (int c : capacity) {
            sum += c;
            count++;
            if (sum >= total) return count;
        }
        return count;
    }
};
